def norm(s): 
    if not s: return ""
    return " ".join(s.translate(char_map).lower().split())
already_read = {(norm(r["title"]), norm(r["authors"])) for r in log if r["title"]}
def is_read(t,a): return (norm(t), norm(a)) in already_read
def prate(r):
    s = r["My Rating"].strip(); return float(s) if s else None

# Get author ratings summary
from collections import defaultdict
author_ratings = defaultdict(list)
for r in log:
    if prate(r) is not None:
        author_ratings[r["authors"]].append(prate(r))

# High-signal authors with unread catalog books
high_authors = []
for a, rates in author_ratings.items():
    if max(rates) >= 4.5 and len([x for x in rates if x >= 4.0]) >= 1:
        high_authors.append((a, max(rates), len(rates), sum(rates)/len(rates)))
high_authors.sort(key=lambda x: (-x[1], -x[2]))

print("=== High-signal authors (>=4.5 best, with 4.0+ history) ===")
