import json, csv
with open("Library_Catalog.json") as f: cat = json.load(f)
with open("Reading_Log.csv", encoding="utf-8") as f: log = list(csv.DictReader(f))
char_map = {0x2018:"'",0x2019:"'",0x201C:'"',0x201D:'"',0x2013:"-",0x2014:"-"}
def norm(s): return " ".join((s or "").translate(char_map).lower().split())
already_read = {(norm(r["title"]), norm(r["authors"])) for r in log if r["title"]}
def is_read(t,a): return (norm(t), norm(a)) in already_read

def list_genre(genre, min_gr=4.0, limit=30):
    out = []
    for k, e in cat["entries"].items():
        if (e.get("primary_genre") or "").lower() != genre.lower(): continue
        if is_read(e.get("title",""), e.get("author","")): continue
        gr = e.get("goodreads_rating") or 0
        if gr < min_gr: continue
        sp = (e.get("series_position") or "").lower()
        if e.get("series") and sp:
            if "book 0" in sp or ("novella" in sp and "book 1" not in sp) or "prequel" in sp.lower(): continue
            if not (sp == "book 1" or sp.startswith("book 1") or "standalone" in sp or "1 of" in sp):
                continue
        out.append((gr, e.get("goodreads_reviews") or 0, e.get("series_status"), e.get("indie"), e.get("pages"), k))
    out.sort(key=lambda x: (-x[0], -x[1]))
    return out[:limit]

print("=== SCIENCE FICTION (>=4.0, unread, series-1 or standalone) ===")
for gr, rev, ss, ind, p, k in list_genre("Science Fiction", limit=40):
    print(f"  [{gr}/{rev}] {ss} | indie={ind} | {p}p | {k}")
print("\n=== LITERARY FICTION ===")
for gr, rev, ss, ind, p, k in list_genre("Literary Fiction", limit=20):
    print(f"  [{gr}/{rev}] {ss} | indie={ind} | {p}p | {k}")
print("\n=== FANTASY ===")
for gr, rev, ss, ind, p, k in list_genre("Fantasy", limit=30):
    print(f"  [{gr}/{rev}] {ss} | indie={ind} | {p}p | {k}")
EOF

